            #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
              label: "Fiscal Year",
              placeholder: "Fiscal Year",
              choiceLabels: ri!fYearDropDown,
              choiceValues: ri!fYearDropDown,
              value: ri!yearFilter,
              saveInto: {
                ri!yearFilter,
                a!save(
                  ri!documentId,
                  null
                ),
                a!save(
                  ri!paging,
                  #"SYSTEM_SYSRULES_pagingInfo"(
                    startIndex: 1,
                    batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
                    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "nominationId")
                  )
                )
              }
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
              label: "Type",
              placeholder: "Select a Type",
              choiceLabels: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934538",
              choiceValues: {#"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4233557", #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562"},
