                a!save(
                  ri!documentId,
                  null
                ),
                a!save(
                  ri!paging,
                  #"SYSTEM_SYSRULES_pagingInfo"(
                    startIndex: 1,
                    batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
                    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "nominationId")
                  )
                )
              }
            )
          }
        ),
        /*a!columnLayout(*/
          /*contents: {*/
            /*a!multipleDropdownField(*/
              /*label: "Region",*/
              /*placeholder: "Select a Region",*/
              /*choiceLabels: cons!CAW_TXT_ASK_REGION_LIST,*/
              /*choiceValues: cons!CAW_TXT_ASK_REGION_LIST,*/
              /*value: ri!regionFilter,*/
              /*saveInto: {*/
                /*ri!regionFilter,*/
                /*a!save(*/
                  /*ri!documentId,*/
                  /*null*/
                /*),*/
                /*a!save(*/
                  /*ri!paging,*/
                  /*a!pagingInfo(*/
                    /*startIndex: 1,*/
                    /*batchSize: cons!CAW_INT_GRID_BATCH_SIZE,*/
                    /*sort: a!sortInfo(field: "nominationId")*/
                  /*)*/
                /*)*/
              /*}*/
            /*)*/
          /*}*/
        /*),*/
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
              label: "Originating BU",
