            #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
              label: "Sub-position",
              placeholder: "Select a Sub-position",
              choiceLabels: property(ri!subPositionDropDown,"subPosition",tostring(null)),
              choiceValues: property(ri!subPositionDropDown,"subPositionId",tostring(null)),
              value: ri!subPositionFilter,
              saveInto: {
                ri!subPositionFilter,
                a!save(
                  ri!documentId,
                  null
                ),
                a!save(
                  ri!paging,
                  #"SYSTEM_SYSRULES_pagingInfo"(
                    startIndex: 1,
                    batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
                    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "nominationId")
                  )
                )
              },
              disabled: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!positionFilter)
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_pickerFieldCustom"(
            label: "Candidate Name",
            placeholder: "Enter at least " & #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3895397" & " characters to search for a candidate",
            suggestFunction: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_4036061"(filter: _),
            selectedLabels: ri!nameFilter,
            value: ri!nameFilter,
            saveInto: {
              ri!nameFilter,
              a!save(
                ri!documentId,
                null
              ),
              a!save(
                ri!paging,
                #"SYSTEM_SYSRULES_pagingInfo"(
                  startIndex: 1,
                  batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
                  sort: #"SYSTEM_SYSRULES_sortInfo"(field: "nominationId")
                )
              )
            }
          )
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
              label: "Status",
              placeholder: "Select a Status",
              choiceLabels: #"_a-0000e6c7-249e-8000-9bfe-011c48011c48_3640108",
              choiceValues: #"_a-0000e6c7-249e-8000-9bfe-011c48011c48_3640108",
              value: ri!statusFilter,
              saveInto: {
                ri!statusFilter,
                a!save(
                  ri!documentId,
                  null
                ),
                a!save(
                  ri!paging,
                  #"SYSTEM_SYSRULES_pagingInfo"(
                    startIndex: 1,
                    batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
                    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "nominationId")
                  )
                )
              }
            )
          }
        )
      }
